'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',layers:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',doc:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',box:'m3 7 9-4 9 4v10l-9 4-9-4z M3 7l9 5 9-5 M12 12v9',people:'M16 21v-3a4 4 0 0 0-8 0v3 M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-3a5 5 0 0 0-2-4',clock:'M12 8v5l3 2 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 18h.01 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',in:'M12 3v12 m-4-4 4 4 4-4 M4 14v7h16v-7',move:'M3 7h18 m-4-4 4 4-4 4 M21 17H3 m4-4-4 4 4 4',plus:'M12 7v10 M7 12h10 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',minus:'M7 12h10 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',check:'m5 12 4 4L19 6',out:'M3 6h12v12H3z M15 10h4l3 4v4h-7 M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',search:'M16 16l5 5 M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',scan:'M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 7v10 M11 7v10 M14 7v10 M17 7v10',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.box}"/></svg>`;
const desktopHidden=['Документы','Остатки','Сотрудники','Помощь'];
const isDesktop=()=>document.body.classList.contains('desktop');
const btn=(label,action,arg='',cls='')=>(action==='nav'&&(arg==='Сотрудники'||isDesktop()&&desktopHidden.includes(arg)))?'':`<button class="${cls}" data-action="${action}" data-arg="${esc(arg)}">${label}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const operations=['Приёмка','Перемещение','Оприходование','Списание','Инвентаризация','Отгрузка'];
const opIcons=['in','move','plus','minus','check','out'];
const opHints=['Принять поставку в ячейку','Перенести запас между ячейками','Учесть обнаруженный товар','Зафиксировать брак и потери','Пересчитать фактический остаток','Проверить и отгрузить заказ'];
const cells=['A-1-1','A-2-5','A-3-2','B-1-4','B-2-1','C-1-2','C-2-3','D-1-1'];
const products=[['60992-10','Тёплый лён','A-2-5',32],['12003-07','Мягкий камень','B-1-4',18],['12002-01','Светлый песок','A-1-1',26],['60647-05','Шёлковая фактура','A-3-2',14],['LD31264-12a','Пудровая геометрия','B-2-1',22],['12006-01','Дымчатый бетон','C-2-3',9],['60992-04','Графитовый лён','D-1-1',16],['12003-02','Молочный камень','C-1-2',24]].map((a,i)=>({sku:a[0],name:a[1],cell:a[2],initial:a[3],code:'46000000000'+(i+1),category:['Лён','Камень','Песок','Шёлк','Геометрия','Бетон','Лён','Камень'][i]}));
const tasks=Array.from({length:24},(_,i)=>({id:'DEMO-'+String(i+1).padStart(3,'0'),p:i%8,q:i%5===1?2:1,market:['WB','Ozon','WB'][i%3],deadline:i<12?'Сегодня, 16:00':'Сегодня, 18:00'}));
const who=()=>$('employee').value,role=()=>$('role').value,supervisor=()=>role()==='Старший смены';
function fresh(){const logs=Array.from({length:18},(_,i)=>({time:`09:${String(10+i*2).padStart(2,'0')}`,who:['Мария','Ирина','Олег','Анна'][i%4],device:'ТСД '+(i%4+1),action:(i%3===0?'Приёмка ':'Отбор ')+products[i%8].sku,result:'Подтверждено',qty:i%3+1,seed:true})).reverse();return {inventory:products.map(p=>({[p.cell]:p.initial,'РЕЗЕРВ':0})),wave:null,archive:[],completed:[],log:logs,docs:[{id:'DEMO-IN-014',kind:0,p:0,qty:12,from:'Поставка',to:'A-2-5',reason:'Учебная поставка 014',who:'Ирина',status:'Передан',seed:true},{id:'DEMO-OUT-008',kind:5,p:2,qty:4,from:'A-1-1',to:'Отгрузка',reason:'Учебная отгрузка 008',who:'Анна',status:'Передан',seed:true},... [1,2,3,4].map((kind,i)=>({id:'DEMO-EX-'+(i+1),kind,p:i,qty:i+1,from:products[i].cell,to:kind===1?'C-1-2':products[i].cell,reason:'Учебный пример: '+operations[kind],who:['Олег','Мария','Анна','Ирина'][i],status:kind===4?'Черновик':'Передан',seed:true}))],seq:20,view:innerWidth<761?'Операции':'Смена',selected:tasks.slice(0,6).map(t=>t.id),guide:true,docId:null,chat:[{from:'bot',text:'Здравствуйте! Помогу разобраться с операцией на складе. Что произошло и на каком шаге?'}],topic:null,tickets:[],generation:Date.now(),search:'',low:false,filters:{orders:{},journal:{},stock:{}},filterOpen:{},worker:'Мария'};}
let state=fresh(),op=null;
// All data and mutations are tab-local. No fetch, network APIs or persisted credentials.
state.inventory[0]['C-1-2']=6;
function record(action,result='Подтверждено',qty=0){state.log.unshift({time:shiftClock(),at:Date.now(),who:who(),device:'ТСД '+(['Мария','Ирина','Олег','Анна'].indexOf(who())+1),action,result,qty});}
function notice(s,error=false){$('notice').textContent=s;$('notice').className=error?'error':'success';if(s&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$('notice').animate([{opacity:0,transform:'translateY(-5px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'ease-out'});const target=document.querySelector('.pick-card')||document.querySelector('.form-grid');if(target)target.animate(error?[{transform:'translateX(0)'},{transform:'translateX(-3px)'},{transform:'translateX(3px)'},{transform:'translateX(0)'}]:[{boxShadow:'0 0 0 2px #b9d8c9'},{boxShadow:'0 0 0 0 transparent'}],{duration:error?230:400});}}
function fail(s){record(s,'Отказ');state.log[0].errorGroup=/ячейк|код|скан|Товар не соответствует/.test(s)?'Сканирование':/остат|запас/.test(s)?'Остаток':/прав|доступ|старш|назначенн/.test(s)?'Права':'Порядок действий';notice(s,true);}
function total(p){return Object.values(state.inventory[p]).reduce((a,b)=>a+b,0);}
function available(p,cell){return state.inventory[p][cell]||0;}
function allowed(kind){return supervisor()||(role()==='Сборщик'&&[0,1].includes(kind))||(role()==='Станция'&&kind===5);}
function table(headers,rows){return `<div class="table"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td data-label="${esc(headers[i])}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function embeddedScreen(){return document.body.classList.contains('device-preview')||document.body.classList.contains('large-preview');}
function topOfScreen(){if(embeddedScreen())document.querySelector('.shell').scrollTop=0;else window.scrollTo({top:0,left:0,behavior:'instant'});}
function navigate(v){closeMenu();state.orderTab='ready';state.view=v;op=null;state.docId=null;state.orderId=null;state.stockId=null;state.waveDetail=null;notice('');render();topOfScreen();}
function applyMode(){const mode=$('mode').value;document.body.className=mode==='terminal'?'terminal device-preview':mode==='large'?'terminal large-preview':mode==='auto'?(innerWidth<761?'terminal':'desktop'):'desktop';const frame=document.querySelector('.device-frame');if(mode==='terminal'){frame.style.setProperty('--device-scale',frame.getBoundingClientRect().width*285/420/360);}$('deviceToggle').textContent=mode==='terminal'?'Вернуться к сводке':'Посмотреть на ТСД';}
const navs=[['Смена','grid'],['Волны','layers'],['Операции','scan'],['Документы','doc'],['Остатки','box'],['Журнал','clock'],['Помощь','help']];
let previousView='';
function render(){const outerX=scrollX,outerY=scrollY,shell=document.querySelector('.shell'),innerY=shell.scrollTop,oldView=previousView;closeMenu();document.documentElement.classList.toggle('clean-view',!!state.clean);$('cleanToggle').textContent=state.clean?'Показать пояснения':'Скрыть пояснения';$('cleanToggle').setAttribute('aria-pressed',String(!!state.clean));if(state.view==='Сотрудники')state.view='Смена';if(isDesktop()&&desktopHidden.includes(state.view)){state.view='Смена';op=null;state.docId=null;}const viewKey=state.view+(op?op.kind:'');$('view').classList.toggle('view-enter',viewKey!==previousView);previousView=viewKey;document.querySelector('main').classList.toggle('home-screen',state.view==='Операции'&&!op);const names={'Смена':'Обзор смены','Помощь':'Помощь сотруднику','Волны':state.orderId?'Заказ':state.waveDetail?'Волна':state.wave?'Отбор волны':'Заказы и волны','Операции':op?operations[op.kind]:'ЛУКДЕКОР','Документы':state.docId?'Документ':'Документы'};$('title').textContent=names[state.view]||state.view;$('sectionLabel').textContent=`СКЛАД ФБС · ${role().toUpperCase()}`;$('nav').dataset.person=who()+' · '+role();$('nav').innerHTML=navs.filter(([v])=>!isDesktop()||!desktopHidden.includes(v)).map(([v,i])=>btn(`${icon(i)}<span>${v}</span>${v==='Волны'?`<span class="nav-count">${state.wave?'1':tasks.length-state.completed.length}</span>`:''}`,'nav',v,state.view===v?'active':'')).join('');$('view').innerHTML=({'Смена':dashboard,'Волны':waves,'Операции':ops,'Документы':documents,'Остатки':stocks,'Сотрудники':employees,'Журнал':journal,'Помощь':help}[state.view])();if(state.view==='Волны'&&state.wave&&!state.orderId&&!state.waveDetail&&state.orderTab!=='all')$('view').insertAdjacentHTML('afterbegin',`<div class="wave-links">${btn('Все заказы','orderTab','all')}${btn('Состав волны','waveDetail',state.wave.number)}</div>`);enhanceSelects();renderTour();if(embeddedScreen()){shell.scrollTop=oldView===viewKey?innerY:0;window.scrollTo({left:outerX,top:outerY,behavior:'instant'});}requestAnimationFrame(()=>{const host=document.body.classList.contains('device-preview')||document.body.classList.contains('large-preview')?document.querySelector('.shell'):document.scrollingElement;document.querySelector('.scroll-dock').hidden=host.scrollHeight<=host.clientHeight+2;});}
function activity(limit=5){return state.log.slice(0,limit).map(l=>`<div class="activity"><time>${l.time}</time><div><b>${esc(l.who)}</b> · ${esc(l.action)}<br><small>${esc(l.device)} · ${esc(l.result)}${l.seed?' · пример смены':''}</small></div></div>`).join('');}
function peopleTable(){return table(['Сотрудник','Роль','Единиц','Шт/ч','Действий','Отказов'],['Мария','Ирина','Олег','Анна'].map((n,i)=>{const logs=state.log.filter(l=>l.who===n);return [`<div class="person"><span class="avatar">${n[0]}</span><b>${n}</b></div>`,['Сборка','Приёмка','Перемещение','Станция'][i],logs.reduce((a,l)=>a+(l.qty||0),0),Math.round(logs.reduce((a,l)=>a+(l.qty||0),0)/(1+(Date.now()-state.generation)/3600000)),logs.filter(l=>l.result==='Подтверждено').length,logs.filter(l=>l.result==='Отказ').length];}));}
function shiftClock(){const minutes=600+Math.floor((Date.now()-state.generation)/60000);return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}
function shiftOverview(){const stages=['К сборке','В сборке','На станции','Отгружен'];const counts=Object.fromEntries(stages.map(k=>[k,tasks.filter(t=>orderStatus(t)===k).length]));return {counts,done:counts['Отгружен'],errors:state.log.filter(l=>l.result==='Отказ'),pending:state.docs.filter(d=>d.status==='Передаётся'),drafts:state.docs.filter(d=>d.status==='Черновик'),sent:state.docs.filter(d=>d.status==='Передан'),hours:1+(Date.now()-state.generation)/3600000};}
function overviewOrders(status='',deadline='',market=''){state.filters.orders={status,deadline,market};navigate('Волны');state.orderTab=status==='К сборке'&&!state.wave?'ready':'all';render();topOfScreen();}
function overviewJournal(filters={}){state.filters.journal=filters;navigate('Журнал');}
function teamOverview(){const kind=state.teamKind||'Сборка',m=shiftOverview();return `<div class="card overview-team"><div class="section-head"><div><h3>Работа команды</h3><small>Выработка по выбранной операции</small></div><label>Операция<select id="teamKind">${['Сборка',...operations].map(k=>`<option ${kind===k?'selected':''}>${k}</option>`).join('')}</select></label></div><div class="team-list">${['Мария','Ирина','Олег','Анна'].map((name,i)=>{const logs=state.log.filter(l=>l.who===name),accepted=logs.filter(l=>l.result==='Подтверждено'&&(kind==='Сборка'?l.action.startsWith('Отбор '):l.action.startsWith(kind+' '))),units=accepted.reduce((n,l)=>n+(l.qty||0),0),errors=logs.filter(l=>l.result==='Отказ').length,last=logs[0],w=state.wave,assigned=w?.worker===name&&w.stage!=='Завершена',status=assigned?(w.shortage!==null?'Ждёт решения':w.stage==='На станции'?'Передал на станцию':'Отбирает волну '+w.number):'Нет назначенной волны';return `<div class="team-member"><div class="team-person"><span class="avatar">${name[0]}</span><div>${btn(name,'overviewEmployee',name,'text-link')}<small>ТСД ${i+1} · ${status}</small></div></div><div class="team-numbers"><div><b>${units}</b><small>шт</small></div><div><b>${Math.round(units/m.hours)}</b><small>шт/ч смены</small></div><div><b>${accepted.length}</b><small>действий</small></div><div>${btn(String(errors),'overviewEmployeeErrors',name,errors?'error-number':'text-link')}<small>отказов всего</small></div></div><div class="team-last">${last?`${last.time} · ${esc(last.action)}`:'Действий ещё нет'}</div></div>`;}).join('')}</div><details class="metric-method"><summary>Как считаются показатели</summary><p>Штуки и действия: только подтверждённые записи выбранной операции. Шт/ч смены: количество с 09:00, делённое на длительность учебной смены. Это не скорость активной работы. Отказы показаны по всем операциям отдельно. Пересчитанные единицы инвентаризации не считаются собранными заказами. Исходные примеры отмечены в журнале.</p></details></div>`;}
function overviewDeadlines(){return `<div class="card"><div class="section-head"><h3>Сроки отгрузки</h3>${tag('Сегодня')}</div><div class="deadline-list">${['Сегодня, 16:00','Сегодня, 18:00'].map(deadline=>{const list=tasks.filter(t=>t.deadline===deadline),done=list.filter(t=>state.completed.includes(t.id)).length;return `<div class="deadline-group"><div class="row spread"><b>До ${deadline.slice(-5)}</b><span>${done} / ${list.length} заказов</span></div><div class="progress"><i style="width:${100*done/list.length}%"></i></div>${['WB','Ozon'].map(market=>{const batch=list.filter(t=>t.market===market),remaining=batch.filter(t=>!state.completed.includes(t.id));return btn(`<span>${market}</span><span>${remaining.length} осталось <i aria-hidden="true">→</i></span>`,'overviewDeadline',deadline+'|'+market,'deadline-link');}).join('')}</div>`;}).join('')}</div><small class="demo-explainer">Прогресс показывает подтверждённые отгрузки. Прогноз срока без замера темпа не рассчитывается.</small></div>`;}
function overviewAttention(m){const w=state.wave,shortage=w?.shortage!=null,cancelled=w?.cancelled&&w.stage!=='Завершена',count=Number(shortage)+Number(!!cancelled);return `<div class="card attention-panel"><div class="section-head"><h3>Требует решения</h3>${tag(count?count+' открыто':'Нет открытых',count?'warn':'')}</div>${shortage?`<div class="exception"><b>Нет на месте · ${products[w.shortage].sku}</b><p>Волна ${w.number} · ${esc(w.worker)} · ${esc(w.route[w.index].cell)}. Требуется ${w.route[w.index].qty-w.route[w.index].picked} шт. В ячейке C-1-2: ${available(w.shortage,'C-1-2')} шт.</p>${btn('Подтвердить другую ячейку','resolve')}</div>`:''}${cancelled?`<div class="exception"><b>Заказ отменён на станции</b><p>Волна ${w.number}. Подтверждение остановлено до решения старшего.</p>${btn('Разобрать отмену','overviewCurrentWave')}</div>`:''}${!count?'<div class="clear-state"><span>✓</span><div><b>Сборка не заблокирована</b><small>Нет открытого дефицита или отмены задания.</small></div></div>':''}<div class="attention-footer"><span>Отказы проверок за смену <b>${m.errors.length}</b></span>${btn('Разобрать в журнале','overviewErrors','','text-link')}</div></div>`;}
function overviewWave(){const w=state.wave;return `<div class="card"><div class="section-head"><h3>Текущая волна</h3>${tag(w?w.stage:'Не назначена',w?.shortage!=null?'warn':'')}</div>${w?`<div class="wave-heading"><div><b>Волна ${w.number}</b><small>${esc(w.worker)} · ${w.ids.length} заказов</small></div>${btn('Открыть','overviewCurrentWave','','soft')}</div><div class="progress"><i style="width:${100*w.picked/w.required}%"></i></div><div class="wave-measures"><span><b>${w.picked}/${w.required}</b> шт отобрано</span><span><b>${w.packed.length}/${w.ids.length}</b> заказов проверено</span></div>${w.stage==='В отборе'&&w.index<w.route.length?`<p class="wave-location">Текущая ячейка <b>${esc(w.route[w.index].cell)}</b> · ${products[w.route[w.index].p].sku}</p>`:''}${w.stage==='Завершена'?btn('Состав и отгрузка','waveDetail',w.number,'wide-button'):''}`:`<div class="clear-state"><span>${icon('layers')}</span><div><b>${tasks.filter(t=>orderStatus(t)==='К сборке').length} заданий к сборке</b><small>Сборщик ещё не назначен</small></div></div>${btn('Назначить волну','overviewReady','','primary wide-button')}`}<div class="overview-archive">Завершено волн: <b>${state.archive.length+(w?.stage==='Завершена'?1:0)}</b>${state.archive.length?btn('Открыть архив','overviewArchive','','text-link'):''}</div></div>`;}
function overviewExchange(m){return `<div class="card"><div class="section-head"><h3>Обмен с МойСклад</h3>${tag('Имитация')}</div><div class="exchange-counts"><div><strong>${m.sent.length}</strong><small>Передано</small></div><div><strong>${m.pending.length}</strong><small>В очереди</small></div><div><strong>${m.drafts.length}</strong><small>Черновики</small></div></div><div class="exchange-docs">${[...m.pending,...m.drafts,...m.sent.slice(-2)].slice(0,4).map(d=>btn(`<span><b>${d.id}</b><small>${operations[d.kind]} · ${esc(d.who)}</small></span>${tag(d.status,d.status==='Черновик'?'warn':'')}`,'linkedDoc',d.id,'exchange-doc')).join('')}</div><small class="demo-explainer">Статусы учебные. Реальный канал обмена и связь устройств не измеряются.</small></div>`;}
function overviewQuality(m){const groups=['Сканирование','Остаток','Права','Порядок действий'];return `<div class="card"><div class="section-head"><h3>Контроль ошибок</h3>${tag(m.errors.length+' отказов',m.errors.length?'warn':'')}</div>${groups.map(g=>btn(`<span>${g}</span><b>${m.errors.filter(l=>(l.errorGroup||'Порядок действий')===g).length}</b>`,'overviewErrorGroup',g,'quality-row')).join('')}<div class="quality-note"><b>Технические сбои</b><small>Телеметрия не подключена</small></div><small class="demo-explainer">Отказ означает заблокированное действие, а не ошибочно отгруженный заказ.</small></div>`;}
function dashboard(){const m=shiftOverview();return `<div class="overview"><div class="overview-top"><div><b>Сегодня · склад ФБС</b><small>Учебная смена с 09:00 · время ${shiftClock()}</small></div><div class="actions">${btn('Обновить сводку','refreshOverview')}${btn('Задания','overviewReady','','primary')}</div></div><div class="hero overview-demo"><div><h2>Проверьте склад в работе</h2><p>От заказа до отгрузки: действия сразу отражаются в сводке.</p></div>${btn('Пройти демонстрацию','startTour','','tour-cta')}</div><div class="overview-stages">${[['К сборке','Ожидают назначения'],['В сборке','Отбор по ячейкам'],['На станции','Проверка заказов'],['Отгружен','Заказы подтверждены']].map(([k,h],i)=>btn(`<span>${i===3?'Отгружено':k}</span><strong>${m.counts[k]}</strong><small>${h}</small>`,'overviewStage',k,'stage-card stage-'+i)).join('')}</div><div class="overview-grid"><div class="overview-main">${overviewAttention(m)}${teamOverview()}<div class="overview-pair">${overviewQuality(m)}<div class="card"><div class="section-head"><h3>Последние действия</h3>${btn('Весь журнал','overviewAllJournal','','text-link')}</div>${activity(5)}</div></div></div><div class="overview-side">${overviewDeadlines()}${overviewWave()}${overviewExchange(m)}</div></div></div>`;}

function oldWavePicker(){const list=tasks.filter(t=>!state.completed.includes(t.id));return `${state.guide?`<div class="guide">${btn('×','dismiss','','close')}<div><b>Попробуйте полный путь заказа</b><small>Создайте волну → проверьте ячейку → сканируйте товар → передайте на станцию.</small></div></div>`:''}<div class="card"><div class="section-head"><h3>Задания на сборку</h3>${tag(list.length+' ожидают')}</div><div class="toolbar-line">${btn('Выбрать найденные · до 20','select20')}${btn('Снять выбор','selectNone')}<small>До 20 заказов в волне</small></div>${table(['','Задание','Товар','Шт','Срок'],list.map(t=>[`<input type="checkbox" name="task" value="${t.id}" ${state.selected.includes(t.id)?'checked':''} aria-label="${t.id}">`,`<b>${t.id}</b><br><small>${t.market}</small>`,`${products[t.p].sku}<br><small>${products[t.p].name}</small>`,t.q,t.deadline]))}<div class="row spaced"><label>Сборщик<select id="worker">${['Мария','Ирина','Олег'].map(n=>`<option ${state.worker===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="selected-bar"><span id="selection">Выбрано ${state.selected.length} из ${list.length}</span>${btn('Создать волну','create','','primary')}</div></div>`;}
function waves(){if(state.orderId)return orderDetails(state.orderId);if(state.waveDetail)return waveDetails(state.waveDetail);if(['all','waves'].includes(state.orderTab))return wavePicker();const w=state.wave;if(!w)return wavePicker();if(w.stage==='Завершена')return `<div class="card empty"><div class="success">✓</div><h2>Волна ${w.number} завершена</h2><p>${w.ids.length} заказов проверены. ${w.required} единиц переданы в учебную отгрузку.</p><div class="actions">${btn('Следующая волна','nextWave','','primary')}${btn('Документ отгрузки','nav','Документы')}</div></div>`;if(w.stage==='На станции')return station();if(w.shortage!==null)return `<div class="card empty"><div class="success">!</div><h2>Ждём решения старшего</h2><p>${products[w.shortage].sku} отсутствует в ${esc(w.route[w.index].cell)}. Дефицит зафиксирован, отбор не завершён.</p>${btn('Открыть исключение','nav','Смена','primary')}</div>`;if(w.index>=w.route.length)return `<div class="card empty"><div class="success">✓</div><h2>Отбор завершён</h2><p>Все ${w.required} единиц проверены. Передайте собранные товары на станцию.</p>${btn('Передать на станцию','transfer','','primary')}</div>`;const r=w.route[w.index],p=products[r.p];return `<div class="pick-layout"><div class="card pick-card"><div class="row spread">${tag('Волна '+w.number+' · '+w.ids.length+' заказов')}<small>${w.picked} из ${w.required} шт</small></div><div class="progress"><i style="width:${100*w.picked/w.required}%"></i></div><div class="stepbar"><span class="${!w.cellOk?'current':''}">1 · Ячейка</span><span class="${w.cellOk?'current':''}">2 · Товар</span><span>3 · Станция</span></div><div class="cell-label">${w.cellOk?'ЯЧЕЙКА ПРОВЕРЕНА':'ОТСКАНИРУЙТЕ ЯЧЕЙКУ'}</div><div class="big">${r.cell}</div><h2>${p.sku}</h2><p>${p.name}</p><div class="pick-qty">Возьмите <b>${r.qty-r.picked} шт</b></div><small>Для ${tasks.filter(t=>w.ids.includes(t.id)&&t.p===r.p).length} заказов</small><form id="pickForm" class="scan"><input id="scan" placeholder="${w.cellOk?'Скан товара':'Скан ячейки'}" aria-label="Скан ячейки или товара" autocomplete="off"><button class="primary">${icon('scan')}</button></form><div class="actions">${btn('Скан верного кода','samplePick','','primary')}${btn('Нет на месте','shortage')}${btn('Неверный товар','wrong','','danger')}</div><p class="scan-hint">В демо кнопка заменяет сканер. Код: ${w.cellOk?p.code:r.cell}</p></div><div class="card pick-route"><div class="section-head"><h3>Маршрут отбора</h3>${tag(w.route.length+' ячеек')}</div>${w.route.map((x,i)=>`<div class="route-stop ${i===w.index?'current':''} ${i<w.index?'done':''}"><span class="num">${i<w.index?'✓':i+1}</span><div><b>${x.cell}</b><small>${products[x.p].sku}</small></div><span class="count">${x.picked}/${x.qty}</span></div>`).join('')}<p class="quiet spaced">Одна позиция для нескольких заказов собирается за один подход. Маршрут упорядочен по ячейкам.</p></div></div>`;}
function station(){const w=state.wave,t=tasks.find(t=>w.ids.includes(t.id)&&!w.packed.includes(t.id)),p=products[t.p];return `<div class="card pick-card"><div class="row spread">${tag('Станция · волна '+w.number)}<small>${w.packed.length} из ${w.ids.length} заказов</small></div><div class="stepbar"><span class="${w.station==='product'?'current':''}">1 · Товар</span><span class="${w.station==='confirm'?'current':''}">2 · Заказ</span></div><div class="big">${p.sku}</div><h3>${t.id}</h3><p>${p.name} · ${t.q} шт</p><p>${w.station==='product'?`Сканируйте товар: ${w.units} из ${t.q}`:'Состав заказа проверен'}</p>${w.cancelled?'<div class="exception">Заказ отменён. Подтверждение заблокировано. Решение принимает старший смены.</div>':''}${w.station==='confirm'?btn('Подтвердить заказ','pack','','primary'):`<form id="stationForm" class="scan"><input id="scan" placeholder="Скан кода" aria-label="Скан кода"><button class="primary">Проверить</button></form><div class="actions">${btn('Скан верного кода','sampleStation','','primary')}</div>`}<div class="actions">${btn('Имитировать отмену задания','cancel','','danger')}${w.cancelled?btn('Снять учебную отмену','uncancel'):''}</div></div>`;}
function ops(){if(op)return operationForm();return `<div class="terminal-welcome row spread"><small>Смена с 09:00 · ${esc(who())}</small>${tag('Учебный режим')}</div><div class="operation-grid">${btn(`${icon('layers')}<b>Сборка волной</b><small class="tile-bottom">${state.wave?'Продолжить отбор':(tasks.length-state.completed.length)+' задания · общий маршрут'}</small>`,'nav','Волны','operation-tile featured')}${operations.map((n,i)=>btn(`${icon(opIcons[i])}<b>${n}</b><small class="tile-bottom">${opHints[i]}</small>`,'op',i,'operation-tile')).join('')}${btn(`${icon('search')}<b>Найти товар</b><small class="tile-bottom">Ячейки и остатки</small>`,'nav','Остатки','operation-tile')}</div><form id="quickSearch" class="scan quick-scan"><input id="quickCode" aria-label="Найти по скану" placeholder="Скан товара или ячейки"><button class="primary">${icon('scan')}</button></form>`;}
function cellOptions(value){return cells.map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('');}
function operationForm(){const k=op.kind,p=products[op.p];if(op.done)return `<div class="card empty"><div class="success">✓</div><h2>Операция подтверждена</h2><p>${operations[k]} · ${p.sku} · ${op.qty} шт</p>${tag('Демо-документ создан')}<div class="actions">${btn('Все операции','nav','Операции','primary')}${btn('Открыть документы','nav','Документы')}</div></div>`;return `<div class="grid"><div class="card"><div class="section-head"><h3>${operations[k]}</h3>${tag('Черновик')}</div><p class="quiet">${opHints[k]}. ${[2,3,4].includes(k)?'Подтверждает старший смены.':''}</p><div class="form-grid"><label class="wide">Товар<select id="product">${products.map((x,i)=>`<option value="${i}" ${i===op.p?'selected':''}>${x.sku} · ${x.name}</option>`).join('')}</select></label><label>${k===4?'Фактически, шт':'Количество, шт'}<input id="qty" type="number" min="${k===4?0:1}" step="1" value="${op.qty}"></label><label>В ячейке<div class="summary-line">${available(op.p,op.from)} шт</div></label><label>${[0,2].includes(k)?'Проверяемая ячейка':'Откуда'}<select id="from">${cellOptions(op.from)}</select></label><label>${[0,1,2].includes(k)?'Куда':'Ячейка учёта'}<select id="to">${cellOptions(op.to)}</select></label><label class="wide">${k===3?'Причина списания':'Основание'}<input id="reason" value="${esc(op.reason)}"></label></div><div class="stepbar"><span class="${!op.cellOk?'current':''}">1 · Ячейка</span><span class="${op.cellOk&&!op.checked?'current':''}">2 · Товар</span><span class="${op.checked?'current':''}">3 · Подтверждение</span></div><form id="opForm" class="scan"><input id="scan" aria-label="Скан операции" placeholder="${op.cellOk?'Скан товара':'Скан ячейки'}" autocomplete="off"><button class="primary">Проверить</button></form><p class="scan-hint">Код: ${op.cellOk?p.code:([0,2].includes(k)?op.to:op.from)}</p><div class="actions">${btn(op.cellOk?'Скан верного товара':'Скан верной ячейки','sampleOp')}${btn('Подтвердить операцию','commit','','primary')}${btn('Сохранить черновик','saveDraft')}</div></div><div class="card"><h3>Что проверяет система</h3><div class="route-stop"><span class="num">${op.cellOk?'✓':'1'}</span><div><b>Правильная ячейка</b><small>Скан должен совпасть с документом</small></div></div><div class="route-stop"><span class="num">${op.checked?'✓':'2'}</span><div><b>Правильный товар</b><small>Артикул и штрихкод совпадают</small></div></div><div class="route-stop"><span class="num">3</span><div><b>Количество и права</b><small>Остаток проверяется перед подтверждением</small></div></div><p class="quiet spaced">${k===1?'Переместите часть запаса: количество в исходной ячейке уменьшится, в целевой увеличится.':k===4?'Пересчёт требует подтверждения старшего смены. Разница отражается в журнале.':'Подтверждение создаст учебный документ. Повторное нажатие не повторит движение.'}</p></div></div>`;}
function oldDocuments(){if(state.docId){const d=state.docs.find(x=>x.id===state.docId);return `<div class="card"><div class="section-head"><h3>${d.id}</h3>${tag(d.status,d.status==='Черновик'?'warn':'')}</div><h2>${operations[d.kind]}</h2><p>${d.p===null?'Сводная отгрузка волны':products[d.p].sku} · ${d.qty} шт</p><p class="quiet">${esc(d.reason)} · ${esc(d.who)}</p>${d.status==='Черновик'?`<div class="actions">${btn('Редактировать и проверить','editDraft',d.id,'primary')}</div>`:`<div class="summary-line">${d.status==='Передан'?'✓ Учебный обмен завершён. Данные совпадают.':'Изменения ожидают учебной передачи.'}</div><p class="quiet spaced demo-explainer">Демо обмена: внешние документы не создаются. Исторические примеры не влияют на текущие остатки.</p>`}<div class="actions">${btn('Все документы','nav','Документы')}${!d.seed&&d.status==='Передан'?btn('Имитировать статус из МойСклад','incoming',d.id):''}</div>${d.external?'<p class="ticket">Входящее изменение: документ проверен в МойСклад. Имитация.</p>':''}</div>`;}return `<div class="guide"><div><b>Документы в обе стороны</b><small>Создайте операцию, откройте документ и попробуйте входящее изменение статуса. Обмен здесь учебный.</small></div>${btn('Новая операция','nav','Операции')}</div><div class="doc-list">${state.docs.slice().reverse().map(d=>btn(`<span class="doc-icon">${icon('doc')}</span><span class="doc-info"><b>${operations[d.kind]} · ${d.id}</b><small>${d.p===null?'Волна':products[d.p].sku} · ${d.qty} шт · ${esc(d.who)}${d.seed?' · пример':''}</small></span>${tag(d.status,d.status==='Черновик'?'warn':'')}`,'doc',d.id,'doc-row')).join('')}</div>`;}
function stocks(){if(state.stockId!==null&&state.stockId!==undefined)return productDetails(Number(state.stockId));return filterBar('stock')+`<div class="card" id="stockRows">${stockRows()}</div>`;}
function filteredStock(){const f=state.filters.stock;return products.map((p,i)=>({p,i,n:f.cell?available(i,f.cell):total(i)})).filter(({p,i,n})=>matches(`${p.sku} ${p.name} ${p.code} ${Object.keys(state.inventory[i]).join(' ')}`,f.q||state.search)&&(!f.category||p.category===f.category)&&(!f.cell||n>0)&&(!f.balance|| (f.balance==='positive'?n>0:f.balance==='low'?n>0&&n<15:n===0))).sort((a,b)=>f.sort==='qtyAsc'?a.n-b.n:f.sort==='qtyDesc'?b.n-a.n:a.p.sku.localeCompare(b.p.sku));}
function stockRows(){const rows=filteredStock();if(!rows.length)return '<div class="filter-count">Найдено 0 из '+products.length+' товаров</div>'+emptyFilters();return `<div class="filter-count">Найдено ${rows.length} из ${products.length} товаров · ${rows.reduce((a,r)=>a+r.n,0)} шт${state.filters.stock.cell?' в выбранной ячейке':''}</div>`+rows.map(({p,i,n})=>`<div class="stock-card"><span class="swatch s${i%3}"></span><div>${btn(p.sku,'productDetails',i,'text-link')}<small>${p.name} · ${p.category}</small><div class="stock-cells">${Object.entries(state.inventory[i]).filter(([c,n])=>n>0).map(([c,n])=>`${c}: ${n} шт`).join(' · ')||'Нет доступного остатка'}</div><small>${p.code}</small></div><div class="stock-qty">${n}<small>шт доступно</small></div></div>`).join('')||emptyFilters();}
function employees(){return `<div class="card"><div class="section-head"><h3>Команда склада</h3>${tag('Учебная смена')}</div>${peopleTable()}<p class="quiet spaced">Единицы: сумма подтверждённых количеств в журнале. Шт/ч: единицы за учебный час плюс время с открытия демо. Действия: подтверждения операций. Отказы: проверки, остановившие действие. Стартовые записи являются примером, не фактическими показателями склада.</p></div><div class="grid spaced">${['Мария','Ирина','Олег','Анна'].map((n,i)=>`<div class="card"><div class="person"><span class="avatar">${n[0]}</span><div><b>${n}</b><small style="display:block">ТСД ${i+1} · учебный сотрудник</small></div></div><div class="progress"><i style="width:${Math.min(100,state.log.filter(l=>l.who===n).length*9)}%"></i></div><small>${state.log.filter(l=>l.who===n).length} записей в журнале</small>${btn('Посмотреть действия','employeeLog',n,'spaced')}</div>`).join('')}</div>`;}
function journal(){return filterBar('journal')+`<div id="journalRows">${journalRows()}</div>`;}
function journalRows(){const f=state.filters.journal,logs=state.log.filter(l=>matches(`${l.action} ${l.who} ${l.device} ${l.result}`,f.q)&&(!f.who||l.who===f.who)&&(!f.device||l.device===f.device)&&(!f.result||l.result===f.result)&&(!f.kind||logKind(l)===f.kind)&&(!f.errorGroup||(l.result==='Отказ'&&(l.errorGroup||'Порядок действий')===f.errorGroup))&&(!f.from||l.time>=f.from)&&(!f.to||l.time<=f.to)&&(!f.source||(f.source==='seed'?l.seed:!l.seed))).slice().sort((a,b)=>f.sort==='old'?a.time.localeCompare(b.time):b.time.localeCompare(a.time));return `<div class="filter-count">Найдено ${logs.length} из ${state.log.length} действий · учебная смена</div>`+(logs.length?`<div class="journal-list">${logs.map(l=>`<div class="journal-entry"><div class="row spread"><b>${esc(l.who)}</b>${tag(l.result,l.result==='Отказ'?'error':l.result==='Исключение'?'warn':'')}</div><p>${esc(l.action)}</p><small>${l.time} · ${esc(l.device)} · ${logKind(l)}${l.seed?' · пример смены':''}</small></div>`).join('')}</div>`:emptyFilters());}

function help(){return `<div class="chat-layout"><div class="card chat"><div class="chat-head"><span class="avatar">М</span><div><b>Помощник склада · MAX</b><small>Интерактивный сценарий · нейросеть не подключена</small></div></div><div class="chat-messages" id="chatMessages">${state.chat.map(m=>`<div class="bubble ${m.from==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="chips">${['Нет товара в ячейке','Неверный штрихкод','Документ не передался'].map(s=>btn(s,'question',s)).join('')}</div><form class="chat-form" id="chatForm"><input id="message" aria-label="Сообщение помощнику" placeholder="Опишите ситуацию…" maxlength="1000"><button class="primary">→</button></form><div class="actions">${btn('Обратиться к Максиму','support')}</div>${state.tickets.length?`<div class="ticket">${state.tickets.at(-1).id}: учебное обращение сохранено с историей. Никому не отправлено.</div>`:''}</div><div class="card help-info"><h3>Помощь в момент ошибки</h3><p class="quiet">В рабочей версии модель будет уточнять ситуацию и опираться на базу знаний по вашему софту.</p><div class="route-stop"><span class="num">1</span><div><b>Опишите проблему</b><small>Обычными словами</small></div></div><div class="route-stop"><span class="num">2</span><div><b>Пройдите подсказки</b><small>С учётом выполненных шагов</small></div></div><div class="route-stop"><span class="num">3</span><div><b>Подключите специалиста</b><small>С историей обращения</small></div></div><p class="quiet spaced">Помощник не изменяет остатки и документы. Незнакомая ситуация передаётся человеку.</p></div></div>`;}
function createWave(){if(!supervisor())return fail('Создание волн доступно старшему смены.');if(state.wave)return fail('Завершите текущую волну.');const ids=state.selected.filter(id=>!state.completed.includes(id));if(!ids.length||ids.length>20)return fail('Выберите от 1 до 20 заданий.');const need=products.map(()=>0);tasks.filter(t=>ids.includes(t.id)).forEach(t=>need[t.p]+=t.q);if(need.some((n,i)=>n>available(i,products[i].cell)))return fail('Недостаточно запаса в основных ячейках. Скорректируйте состав волны.');const route=need.map((qty,p)=>({p,qty,picked:0,cell:products[p].cell})).filter(r=>r.qty).sort((a,b)=>a.cell.localeCompare(b.cell));state.orderTab='ready';state.wave={ids,route,index:0,cellOk:false,shortage:null,worker:state.worker,number:state.archive.length+14,required:need.reduce((a,b)=>a+b,0),picked:0,stage:'В отборе',packed:[],station:'product',units:0,cancelled:false};record('Создана волна '+state.wave.number);notice('');render();topOfScreen();}
function canPick(){return supervisor()||(role()==='Сборщик'&&who()===state.wave.worker);}
function pick(code){const w=state.wave;if(!w||w.stage!=='В отборе'||w.shortage!==null||w.index>=w.route.length)return;if(!canPick())return fail('Отбор доступен назначенному сборщику или старшему смены.');const r=w.route[w.index];if(!w.cellOk){if(code!==r.cell)return fail('Неверная ячейка. Операция не подтверждена.');w.cellOk=true;notice('Ячейка проверена. Сканируйте товар.');}else{if(code!==products[r.p].code)return fail('Неверный товар. Количество не изменилось.');if(available(r.p,r.cell)<1)return fail('Недостаточно остатка. Отбор заблокирован.');state.inventory[r.p][r.cell]--;r.picked++;w.picked++;record('Отбор '+products[r.p].sku+' из '+r.cell,'Подтверждено',1);if(r.picked===r.qty){w.index++;w.cellOk=false;}notice('✓ Товар подтверждён · '+w.picked+' из '+w.required+' шт');}render();}
function readOp(){if(!op||!$('product'))return;op.p=Number($('product').value);op.qty=Number($('qty').value);op.from=$('from').value;op.to=$('to').value;op.reason=$('reason').value.trim();}
function checkOp(code){readOp();if(!allowed(op.kind))return fail('Недостаточно прав для этой операции.');if(!op.cellOk){if(code!==([0,2].includes(op.kind)?op.to:op.from))return fail('Неверная ячейка. Проверьте размещение.');op.cellOk=true;notice('Ячейка проверена. Теперь сканируйте товар.');}else{if(code!==products[op.p].code)return fail('Товар не соответствует документу.');op.checked=true;notice('Товар проверен. Подтвердите количество.');}render();}
function sendDoc(d){d.status='Передаётся';const gen=state.generation;setTimeout(()=>{if(state.generation!==gen)return;d.status='Передан';record('Демо-обмен: '+d.id,'Передан');if(['Документы','Смена','Журнал'].includes(state.view))render();},1200);}
function commit(){if(!op||op.done)return;readOp();if(!allowed(op.kind))return fail('Подтверждение этой операции недоступно вашей роли.');if(!op.cellOk||!op.checked)return fail('Сначала проверьте ячейку и товар сканированием.');if(!Number.isInteger(op.qty)||op.qty<0||(op.qty===0&&op.kind!==4))return fail('Укажите допустимое целое количество.');if(!op.reason)return fail('Укажите основание операции.');if([1,3,5].includes(op.kind)&&op.qty>available(op.p,op.from))return fail('Недостаточно остатка. Документ не проведён.');if(op.kind===1&&op.from===op.to)return fail('Ячейки перемещения должны отличаться.');if(op.kind===4&&state.wave&&state.wave.stage!=='Завершена')return fail('Завершите активную волну перед пересчётом.');const inv=state.inventory[op.p];if([0,2].includes(op.kind))inv[op.to]=(inv[op.to]||0)+op.qty;if([1,3,5].includes(op.kind))inv[op.from]-=op.qty;if(op.kind===1)inv[op.to]=(inv[op.to]||0)+op.qty;if(op.kind===4)inv[op.from]=op.qty;let d=state.docs.find(x=>x.id===op.draftId);if(d)Object.assign(d,op,{who:who()});else{d={...op,id:'DEMO-DOC-'+(++state.seq),who:who()};state.docs.push(d);}record(operations[op.kind]+' '+products[op.p].sku+' · '+op.qty+' шт','Подтверждено',op.qty);op.done=true;sendDoc(d);notice('Документ подтверждён только в демо');render();}
function scanStation(code){const w=state.wave;if(!w||w.stage!=='На станции')return;if(!supervisor()&&role()!=='Станция')return fail('Проверка заказа доступна станции или старшему смены.');if(w.cancelled)return fail('Отменённое задание нельзя подтвердить.');const t=tasks.find(t=>w.ids.includes(t.id)&&!w.packed.includes(t.id));const expected=products[t.p].code;if(code!==expected)return fail('Неверный код. Проверка не пройдена.');w.units++;if(w.units===t.q)w.station='confirm';notice('Проверка пройдена');render();}
function pack(){const w=state.wave;if(!w||w.stage!=='На станции'||w.station!=='confirm')return;if(!supervisor()&&role()!=='Станция')return fail('Подтверждение доступно станции.');if(w.cancelled)return fail('Отменённое задание нельзя подтвердить.');const t=tasks.find(t=>w.ids.includes(t.id)&&!w.packed.includes(t.id));w.packed.push(t.id);record('Заказ '+t.id+' проверен на станции');w.units=0;w.station='product';if(w.packed.length===w.ids.length){w.stage='Завершена';state.completed.push(...w.ids);const d={id:'DEMO-WAVE-'+w.number,kind:5,p:null,qty:w.required,who:who(),orderIds:[...w.ids],waveNumber:w.number,reason:'Сводная отгрузка волны '+w.number};state.docs.push(d);sendDoc(d);}notice('Заказ подтверждён');render();}
function question(text){if(!text.trim())return;state.chat.push({from:'user',text:text.trim()});let answer;const s=text.toLowerCase();if(/нет товара|нет на месте|ячейк|дефицит/.test(s)){state.topic='shortage';answer='Проверьте адрес ячейки и артикул на экране. Если товар действительно отсутствует, нажмите Нет на месте. Старший смены увидит дефицит и проверит альтернативную ячейку.\nВы уже проверили соседнюю упаковку в этой же ячейке?';}else if(/штрих|скан|неверн/.test(s)){state.topic='scan';answer='Сверьте артикул на экране с этикеткой товара. На шаге Ячейка нужен код ячейки, на шаге Товар — штрихкод товара. Не подтверждайте другую позицию вручную.\nНа каком шаге возникло сообщение: ячейка или товар?';}else if(/документ|передал|синхрон|обмен/.test(s)){state.topic='sync';answer='Откройте Документы и посмотрите статус нужной операции. Если стоит Передаётся, не создавайте документ повторно. Запишите номер документа.\nКакой статус вы видите сейчас?';}else if(state.topic&&/да|провер|не помог|товар|статус|ошибка/.test(s)){answer='Спасибо, учёл выполненную проверку. Не повторяйте подтверждение и не корректируйте остатки вручную. Передайте обращение Максиму: в него попадут ваши сообщения и пройденные шаги.';state.topic=null;}else{answer='Для этой ситуации в демонстрационной базе нет подтверждённого решения. Укажите операцию и текст ошибки. Можно сразу передать историю Максиму кнопкой ниже.';state.topic=null;}state.chat.push({from:'bot',text:answer});render();$('chatMessages').scrollTop=$('chatMessages').scrollHeight;}
const actions={hardwareScan:()=>{if(state.view==='Волны'&&state.wave?.stage==='В отборе'&&state.wave.shortage===null&&state.wave.index<state.wave.route.length)actions.samplePick();else if(state.view==='Волны'&&state.wave?.stage==='На станции'&&state.wave.station!=='confirm')actions.sampleStation();else if(state.view==='Операции'&&op&&!op.done)actions.sampleOp();else{notice('Выберите операцию для сканирования');$('quickCode')?.focus({preventScroll:true});}},nav:navigate,dismiss:()=>{state.guide=false;render();},select20:()=>{state.selected=filteredOrders().filter(t=>orderStatus(t)==='К сборке').slice(0,20).map(t=>t.id);render();},selectNone:()=>{state.selected=[];render();},create:createWave,samplePick:()=>{const w=state.wave,r=w.route[w.index];pick(w.cellOk?products[r.p].code:r.cell);},wrong:()=>fail('Неверный код. Действие заблокировано.'),shortage:()=>{if(!canPick())return fail('Отбор доступен назначенному сотруднику.');state.wave.shortage=state.wave.route[state.wave.index].p;record('Нет на месте '+products[state.wave.shortage].sku,'Исключение');render();},resolve:()=>{if(!supervisor())return fail('Решение принимает старший смены.');const w=state.wave;if(!w||w.shortage===null)return;const r=w.route[w.index];if(available(r.p,'C-1-2')<r.qty-r.picked||r.cell==='C-1-2')return fail('Подтверждённой альтернативы недостаточно. Дефицит остаётся открытым.');r.cell='C-1-2';w.shortage=null;w.cellOk=false;record('Подтверждена альтернативная ячейка C-1-2');navigate('Волны');},transfer:()=>{if(!canPick())return fail('Передача доступна назначенному сотруднику.');state.wave.stage='На станции';record('Волна передана на станцию');notice('Теперь выберите роль Станция или продолжите как старший смены.');render();},sampleStation:()=>{const w=state.wave,t=tasks.find(t=>w.ids.includes(t.id)&&!w.packed.includes(t.id));scanStation(products[t.p].code);},pack,cancel:()=>{state.wave.cancelled=true;record('Учебная отмена заказа','Исключение');render();},uncancel:()=>{if(!supervisor())return fail('Снять учебную отмену может старший смены.');state.wave.cancelled=false;record('Учебная отмена снята');render();},nextWave:()=>{if(state.wave?.stage!=='Завершена')return;state.archive.push(state.wave);state.wave=null;state.selected=tasks.filter(t=>!state.completed.includes(t.id)).slice(0,6).map(t=>t.id);render();},op:i=>{const k=Number(i);if(!allowed(k))return fail('Эта операция доступна другой роли. Смените роль в настройках демо.');op={kind:k,p:0,qty:1,from:products[0].cell,to:k===1?'C-1-2':products[0].cell,reason:k===3?'Повреждена упаковка':'Учебный документ',cellOk:false,checked:false,done:false};render();},sampleOp:()=>{readOp();checkOp(op.cellOk?products[op.p].code:([0,2].includes(op.kind)?op.to:op.from));},commit,saveDraft:()=>{readOp();if(!allowed(op.kind))return fail('Недостаточно прав.');if(!Number.isInteger(op.qty)||op.qty<0)return fail('Проверьте количество.');let d=state.docs.find(x=>x.id===op.draftId);if(d)Object.assign(d,op);else{d={...op,id:'DEMO-DOC-'+(++state.seq)};state.docs.push(d);}Object.assign(d,{who:who(),status:'Черновик'});record('Сохранён черновик '+d.id);navigate('Документы');},doc:id=>{state.docId=id;render();},editDraft:id=>{const d=state.docs.find(x=>x.id===id);if(!d||d.status!=='Черновик')return;if(!allowed(d.kind))return fail('Недостаточно прав.');state.view='Операции';op={...d,draftId:id,checked:false,cellOk:false,done:false};render();},incoming:id=>{const d=state.docs.find(x=>x.id===id);if(!d||d.external)return;d.external=true;record('Входящий статус из МойСклад: '+id,'Демо-обмен');render();},low:()=>{state.low=!state.low;render();},employeeLog:n=>{state.filters.journal.who=n;navigate('Журнал');},clearFilter:()=>{state.logFilter=null;render();},question,support:()=>{const id='DEMO-HELP-'+String(state.tickets.length+1).padStart(3,'0');state.tickets.push({id,history:state.chat.map(x=>({...x}))});record('Учебное обращение '+id,'Демо');state.chat.push({from:'bot',text:'Обращение '+id+' сохранено вместе с историей диалога. В прототипе уведомления не отправляются.'});render();$('chatMessages').scrollTop=$('chatMessages').scrollHeight;}};
function closeMenu(){document.body.classList.remove('menu-open');document.querySelector('.drawer-layer').hidden=true;$('menuToggle').setAttribute('aria-expanded','false');}
function showMenu(){document.body.classList.add('menu-open');document.querySelector('.drawer-layer').hidden=false;$('menuToggle').setAttribute('aria-expanded','true');$('nav').querySelector('button.active')?.focus({preventScroll:true});}
function scrollBoundary(bottom){const el=document.body.classList.contains('device-preview')||document.body.classList.contains('large-preview')?document.querySelector('.shell'):document.scrollingElement;el.scrollTo({top:bottom?el.scrollHeight:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function orderStatus(t){if(state.completed.includes(t.id))return 'Отгружен';if(state.wave?.ids.includes(t.id))return state.wave.stage==='На станции'?'На станции':'В сборке';return 'К сборке';}
function orderRow(t,selectable=false){return `<div class="order-line ${state.selected.includes(t.id)&&selectable?'selected':''}">${selectable?`<label class="order-check"><input type="checkbox" name="task" value="${t.id}" ${state.selected.includes(t.id)?'checked':''} aria-label="${t.id}"></label>`:''}${btn(`<span class="order-first"><b>${t.id}</b><span>${t.market} · ${t.deadline.replace('Сегодня, ','')}</span></span><span class="order-second">${products[t.p].sku} <b>${t.q} шт</b><em>${orderStatus(t)}</em></span>`,'order',t.id,'order-open')}</div>`;}
function selectionSummary(){const selected=tasks.filter(t=>state.selected.includes(t.id)&&!state.completed.includes(t.id));return `${selected.length} заказов · ${selected.reduce((a,t)=>a+t.q,0)} шт · ${new Set(selected.map(t=>products[t.p].cell)).size} ячеек`;}
const matches=(text,q)=>!q||text.toLocaleLowerCase('ru').includes(q.trim().toLocaleLowerCase('ru'));
const emptyFilters=()=>'<div class="empty-filter">Ничего не найдено. Измените условия или сбросьте фильтры.</div>';
function logKind(l){if(l.result==='Отказ')return 'Проверка';if(l.result==='Исключение'||/альтернативн/.test(l.action))return 'Исключение';if(/обмен|Входящий/.test(l.action))return 'Обмен';if(/обращение/.test(l.action))return 'Поддержка';return operations.find(k=>l.action.startsWith(k))||(/волна|Волна|Заказ|Отбор/.test(l.action)?'Сборка':'Документы');}
function filterSelect(scope,key,label,options){const val=state.filters[scope][key]||'';return `<label>${label}<select id="filter-${scope}-${key}" data-filter-scope="${scope}" data-filter-key="${key}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${val===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function filterBar(scope){const f=state.filters[scope],sel=(key,label,options)=>filterSelect(scope,key,label,[['','Все'],...options]),count=Object.values(f).filter(Boolean).length,search=scope==='stock'?'Артикул, название, штрихкод, ячейка':scope==='orders'?'Номер заказа, артикул, товар, ячейка':'Действие, артикул, документ';let fields='';
if(scope==='orders')fields=sel('market','Маркетплейс',['WB','Ozon'])+sel('status','Статус',['К сборке','В сборке','На станции','Отгружен','Не отгружены'])+sel('deadline','Срок',['Сегодня, 16:00','Сегодня, 18:00'])+sel('cell','Ячейка',cells)+sel('qty','Количество',[['one','1 штука'],['many','Больше 1 штуки']])+sel('sort','Порядок',[['deadline','Сначала ближайший срок'],['sku','По артикулу'],['qty','Сначала больше штук']]);
if(scope==='stock')fields=sel('category','Категория',[...new Set(products.map(p=>p.category))])+sel('cell','Ячейка',cells)+sel('balance','Остаток',[['positive','Есть в наличии'],['low','Мало: менее 15 шт'],['zero','Нет остатка']])+sel('sort','Порядок',[['sku','По артикулу'],['qtyAsc','Сначала меньше'],['qtyDesc','Сначала больше']]);
if(scope==='journal')fields=sel('who','Сотрудник',['Мария','Ирина','Олег','Анна'])+sel('device','Устройство',['ТСД 1','ТСД 2','ТСД 3','ТСД 4'])+sel('kind','Операция',[...operations,'Сборка','Проверка','Исключение','Обмен','Поддержка','Документы'])+sel('result','Результат',['Подтверждено','Отказ','Исключение','Передан','Демо-обмен','Демо'])+sel('errorGroup','Причина отказа',['Сканирование','Остаток','Права','Порядок действий'])+sel('source','Записи',[['seed','Примеры смены'],['session','Мои действия в демо']])+sel('sort','Порядок',[['new','Сначала новые'],['old','Сначала старые']])+['from','to'].map(k=>`<label>${k==='from'?'Время с':'Время до'}<input type="time" data-filter-scope="journal" data-filter-key="${k}" value="${esc(f[k]||'')}"></label>`).join('');
return `<section class="filters"><input class="filter-search" id="filter-search-${scope}" data-filter-scope="${scope}" data-filter-key="q" aria-label="${search}" placeholder="${search}" value="${esc(f.q||(scope==='stock'?state.search:'')||'')}"><div class="row spread filter-controls">${btn('Фильтры'+(count?' · '+count:''),'toggleFilters',scope,state.filterOpen[scope]?'soft':'')}${btn('Сбросить','resetFilters',scope,'text-link')}</div>${state.filterOpen[scope]?`<div class="filter-grid">${fields}</div>${scope==='stock'?'<small class="demo-explainer">Учебные категории по фактуре товара.</small>':''}`:''}</section>`;}
function filteredOrders(){const f=state.filters.orders;return tasks.filter(t=>(state.orderTab==='all'||orderStatus(t)==='К сборке')&&matches(`${t.id} ${products[t.p].sku} ${products[t.p].name} ${products[t.p].code} ${products[t.p].cell}`,f.q)&&(!f.market||t.market===f.market)&&(!f.status||(f.status==='Не отгружены'?!state.completed.includes(t.id):orderStatus(t)===f.status))&&(!f.deadline||t.deadline===f.deadline)&&(!f.cell||products[t.p].cell===f.cell)&&(!f.qty||(f.qty==='one'?t.q===1:t.q>1))).sort((a,b)=>f.sort==='qty'?b.q-a.q:f.sort==='sku'?products[a.p].sku.localeCompare(products[b.p].sku):a.deadline.localeCompare(b.deadline)||a.id.localeCompare(b.id));}
function orderResults(){const rows=filteredOrders();return `<div class="filter-count">Найдено ${rows.length} из ${tasks.length} заданий</div>`+ (rows.map(t=>orderRow(t,state.orderTab!=='all'&&!state.wave)).join('')||emptyFilters());}
function refreshFilterResults(scope){if(scope==='orders'){$('orderResults').innerHTML=orderResults();}if(scope==='stock')$('stockRows').innerHTML=stockRows();if(scope==='journal')$('journalRows').innerHTML=journalRows();}
function wavePicker(){const list=tasks.filter(t=>!state.completed.includes(t.id)),all=state.orderTab==='all';return `<div class="wave-compact"><div class="segmented">${btn('К сборке · '+list.length,'orderTab','ready',!all?'active':'')}${btn('Все заказы · '+tasks.length,'orderTab','all',all?'active':'')}${state.archive.length?btn('Волны · '+state.archive.length,'orderTab','waves',state.orderTab==='waves'?'active':''):''}</div>${state.orderTab==='waves'?`<div class="stack">${state.archive.map(w=>btn(`Волна ${w.number} · ${w.ids.length} заказов · завершена`,'waveDetail',w.number)).join('')}</div>`:`<div class="toolbar-line compact-tools">${!all?btn('Выбрать найденные · до 20','select20')+btn('Снять выбор','selectNone'):''}<span class="quiet">${all?'Нажмите на заказ, чтобы открыть состав':'До 20 заказов в волне'}</span></div>${!all?`<div class="row wave-assignment"><label>Сборщик<select id="worker">${['Мария','Ирина','Олег'].map(n=>`<option ${state.worker===n?'selected':''}>${n}</option>`).join('')}</select></label></div>`:''}${filterBar('orders')}<div class="order-list" id="orderResults">${orderResults()}</div>${!all?`<div class="wave-bottom"><span id="selection">${selectionSummary()}</span>${btn('Создать волну','create','','primary')}</div>`:''}`}</div>`;}
function orderDetails(id){const t=tasks.find(t=>t.id===id),w=[state.wave,...state.archive].find(w=>w?.ids.includes(id)),docs=state.docs.filter(d=>d.orderIds?.includes(id));return `<div class="card detail-card"><div class="section-head">${btn('← К заказам','backOrders')} ${tag(orderStatus(t))}</div><h2>${t.id}</h2><p class="quiet">${t.market} · склад ФБС · ${t.deadline}</p><div class="detail-position"><span class="swatch s${t.p%3}"></span><div>${btn(products[t.p].sku,'productDetails',t.p,'text-link')}<small>${products[t.p].name}</small></div><b>${t.q} шт</b></div><div class="detail-facts"><div><small>Ячейка отбора</small><b>${products[t.p].cell}</b></div><div><small>Доступно на складе</small><b>${total(t.p)} шт</b></div></div><h3>Путь заказа</h3><div class="stepbar"><span class="current">Заказ</span><span class="${w?'current':''}">Волна</span><span class="${state.completed.includes(id)?'current':''}">Отгрузка</span></div>${w?btn(`Открыть волну ${w.number}`,'waveDetail',w.number,'wide-button'):btn('Выбрать для волны','selectOrder',id,'primary wide-button')}${docs.map(d=>btn('Документ '+d.id,'linkedDoc',d.id,'wide-button')).join('')}${!docs.length?'<p class="quiet spaced">Документ отгрузки появится после завершения проверки на станции.</p>':''}</div>`;}
function waveDetails(number){const w=[state.wave,...state.archive].find(x=>x?.number===Number(number));if(!w)return '<p>Волна не найдена</p>';return `<div class="card"><div class="section-head">${btn('← К заказам','backOrders')}${tag(w.stage)}</div><h2>Волна ${w.number}</h2><p class="quiet">${esc(w.worker)} · ${w.picked}/${w.required} шт</p>${w===state.wave&&w.stage!=='Завершена'?btn('Продолжить выполнение','resumeWave','','primary'):''}<div class="order-list spaced">${tasks.filter(t=>w.ids.includes(t.id)).map(t=>orderRow(t)).join('')}</div>${state.docs.filter(d=>d.waveNumber===w.number).map(d=>btn('Отгрузка '+d.id,'linkedDoc',d.id,'wide-button')).join('')}</div>`;}
function productDetails(i){const p=products[i],docs=state.docs.filter(d=>d.p===i||d.orderIds?.some(id=>tasks.find(t=>t.id===id)?.p===i));return `<div class="card"><div class="section-head">${btn('← Назад','backProduct')}${tag(total(i)+' шт')}</div><h2>${p.sku}</h2><p>${p.name}</p><h3>Размещение</h3>${Object.entries(state.inventory[i]).filter(([c,n])=>n>0).map(([c,n])=>`<div class="fact-row"><b>${c}</b><span>${n} шт</span></div>`).join('')||'<p class="quiet">Нет доступного остатка</p>'}<h3 class="spaced">Документы товара</h3>${docs.map(d=>btn(`${operations[d.kind]} · ${d.id} · ${d.qty} шт`,'linkedDoc',d.id,'wide-button')).join('')||'<p class="quiet">Пока нет документов</p>'}<h3 class="spaced">Движения и проверки</h3>${state.log.filter(l=>l.action.includes(p.sku)).slice(0,10).map(l=>`<div class="activity"><time>${l.time}</time><div>${esc(l.action)}<small> · ${esc(l.who)}</small></div></div>`).join('')||'<p class="quiet">Нет движений в этой учебной смене</p>'}</div>`;}
const docGroups=['Приёмки','Перемещения','Оприходования','Списания','Инвентаризации','Отгрузки'];
function documents(){if(state.docId){const d=state.docs.find(d=>d.id===state.docId);return oldDocuments()+`<div class="card spaced"><div class="detail-facts"><div><small>Откуда</small><b>${esc(d.from||'Станция сборки')}</b></div><div><small>Куда</small><b>${esc(d.to||'Отгрузка')}</b></div></div><h3>Связанные данные</h3>${d.p!==null?btn('Товар '+products[d.p].sku,'productDetails',d.p,'wide-button'):''}${d.waveNumber?btn('Волна '+d.waveNumber,'waveDetail',d.waveNumber,'wide-button'):''}${(d.orderIds||[]).map(id=>btn('Заказ '+id,'order',id,'wide-button')).join('')}<h3 class="spaced">История документа</h3>${state.log.filter(l=>l.action.includes(d.id)).map(l=>`<div class="activity"><time>${l.time}</time><div>${esc(l.action)}<small> · ${esc(l.who)}</small></div></div>`).join('')||'<p class="quiet">Исходный пример документа учебной смены.</p>'}</div>`;}const kind=state.docKind??0,filter=state.docFilter||'Все',docs=state.docs.filter(d=>d.kind===kind&&(filter==='Все'||d.status===filter));return `<div class="document-types">${docGroups.map((g,i)=>btn(`<span>${icon(opIcons[i])}${g}</span><b>${state.docs.filter(d=>d.kind===i).length}</b>`,'docKind',i,kind===i?'active':'')).join('')}</div><div class="row spaced"><label>Статус<select id="docStatus">${['Все','Черновик','Передаётся','Передан'].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></label>${btn('Новый документ','newDoc',kind,'primary')}</div><div class="doc-list spaced">${docs.slice().reverse().map(d=>btn(`<span class="doc-icon">${icon(opIcons[d.kind])}</span><span class="doc-info"><b>${d.id}</b><small>${d.p===null?'Волна '+d.waveNumber:products[d.p].sku} · ${d.qty} шт · ${esc(d.who)}</small></span>${tag(d.status,d.status==='Черновик'?'warn':'')}`,'doc',d.id,'doc-row')).join('')||'<div class="card quiet">Документов с таким статусом нет. Можно создать учебный документ кнопкой выше.</div>'}</div>`;}
const tourSteps=[
 ['Откройте заказ','Посмотрите состав заказа DEMO-001.','Заказ открыт',()=>state.tourSeenOrder,()=>actions.order('DEMO-001')],
 ['Создайте общую волну','Выбраны два заказа одного артикула. Назначьте сборщика и создайте волну.','Два заказа объединены в один отбор',()=>!!state.wave,()=>{state.selected=['DEMO-001','DEMO-009'];navigate('Волны');}],
 ['Проверьте защиту','Нажмите Неверный товар. Количество не должно измениться.','Неверный скан остановлен',()=>state.log.some(l=>!l.seed&&l.result==='Отказ'),()=>navigate('Волны')],
 ['Решите дефицит','Нажмите Нет на месте. Откройте исключение и подтвердите резервную ячейку.','Решение старшего возвращает заказ в отбор',()=>state.log.some(l=>l.action.includes('альтернативная')),()=>navigate('Волны')],
 ['Завершите сборку','Сканируйте ячейку и товары, передайте на станцию и подтвердите оба заказа.','Волна завершена, отгрузка создана',()=>state.wave?.stage==='Завершена',()=>navigate('Волны')],
 ['Проверьте результат','Откройте отгрузку, связанные заказы, товар и журнал.','Документ связан с волной и заказами',()=>state.tourSeenDoc,()=>{const d=state.docs.find(d=>d.waveNumber===state.wave?.number);if(d)actions.linkedDoc(d.id);}],
 ['Примите и переместите товар','Выполните приёмку, затем переместите часть товара в другую ячейку.','Обе операции отразились в остатках',()=>state.docs.some(d=>!d.seed&&d.kind===0&&d.status!=='Черновик')&&state.docs.some(d=>!d.seed&&d.kind===1&&d.status!=='Черновик'),()=>navigate('Операции')],
 ['Обратитесь за помощью','Опишите проблему помощнику и передайте историю Максиму.','Учебное обращение зарегистрировано',()=>state.tickets.length>0,()=>navigate('Помощь')]
];
function renderTour(){const bar=$('tourBar');if(!state.tour){bar.innerHTML='';return;}const step=tourSteps[state.tourStep||0];if(!step){bar.innerHTML=`<div class="tour-panel"><b>✓ Демонстрация пройдена</b><small>Вы проверили путь заказа, движение товара и помощь сотруднику. Обновление страницы сбросит смену.</small>${btn('Закрыть','endTour')}</div>`;return;}bar.innerHTML=`<div class="tour-panel"><div class="row spread"><b>${(state.tourStep||0)+1}/${tourSteps.length} · ${step[0]}</b>${btn('×','endTour','','tour-close')}</div><small>${step[1]}</small><div class="row spread"><span class="quiet">${step[3]()?'✓ '+step[2]:'Выполните шаг'}</span>${btn(step[3]()?'Далее →':'Открыть шаг','tourContinue','','soft')}</div></div>`;}
Object.assign(actions,{
 refreshOverview:()=>render(),overviewReady:()=>overviewOrders('К сборке'),overviewStage:status=>overviewOrders(status),overviewDeadline:value=>{const [deadline,market]=value.split('|');overviewOrders('Не отгружены',deadline,market);},overviewEmployee:name=>overviewJournal({who:name}),overviewEmployeeErrors:name=>overviewJournal({who:name,result:'Отказ'}),overviewErrors:()=>overviewJournal({result:'Отказ'}),overviewAllJournal:()=>overviewJournal({}),overviewErrorGroup:g=>overviewJournal({result:'Отказ',errorGroup:g}),overviewCurrentWave:()=>navigate('Волны'),overviewArchive:()=>{navigate('Волны');state.orderTab='waves';render();}
});
document.addEventListener('change',e=>{if(e.target.id==='teamKind'){state.teamKind=e.target.value;render();}});
Object.assign(actions,{
 menu:()=>document.body.classList.contains('menu-open')?closeMenu():showMenu(),closeMenu,scrollTop:()=>scrollBoundary(false),scrollBottom:()=>scrollBoundary(true),
 largeMode:()=>{$('mode').value='large';applyMode();render();topOfScreen();},
 orderTab:tab=>{state.orderTab=tab;render();},order:id=>{navigate('Волны');state.orderId=id;state.tourSeenOrder=true;render();topOfScreen();},backOrders:()=>{state.orderId=null;state.waveDetail=null;state.orderTab='all';render();topOfScreen();},selectOrder:id=>{state.orderId=null;state.orderTab='ready';if(!state.selected.includes(id))state.selected.push(id);render();topOfScreen();},waveDetail:n=>{navigate('Волны');state.waveDetail=Number(n);render();},resumeWave:()=>{state.waveDetail=null;state.orderId=null;state.orderTab='ready';render();},
 productDetails:i=>{if(isDesktop()){$('mode').value='large';applyMode();}state.productReturn={view:state.view,orderId:state.orderId,docId:state.docId};state.view='Остатки';state.stockId=Number(i);render();topOfScreen();},backProduct:()=>{const ret=state.productReturn;state.stockId=null;if(ret)Object.assign(state,ret);render();topOfScreen();},
 linkedDoc:id=>{if(isDesktop()){$('mode').value='large';applyMode();}state.view='Документы';state.docId=id;state.tourSeenDoc=true;render();topOfScreen();},doc:id=>{state.docId=id;state.tourSeenDoc=true;render();topOfScreen();},docKind:i=>{state.docKind=Number(i);state.docFilter='Все';render();},newDoc:i=>{state.view='Операции';actions.op(i);},
 startTour:()=>{state.clean=false;if(state.wave||state.docs.some(d=>!d.seed)){notice('Для прохождения с начала сбросьте учебную смену в настройках демо.');return;}$('mode').value='large';$('role').value='Старший смены';applyMode();state.tour=true;state.tourStep=0;tourSteps[0][4]();},tourContinue:()=>{const step=tourSteps[state.tourStep||0];if(step[3]()){state.tourStep++;const next=tourSteps[state.tourStep];if(next)next[4]();else render();}else step[4]();},endTour:()=>{state.tour=false;renderTour();}
});
Object.assign(actions,{toggleFilters:scope=>{state.filterOpen[scope]=!state.filterOpen[scope];render();},resetFilters:scope=>{state.filters[scope]={};if(scope==='stock')state.search='';render();}});
document.addEventListener('change',e=>{if(e.target.id==='worker')state.worker=e.target.value;const scope=e.target.dataset.filterScope,key=e.target.dataset.filterKey;if(scope&&key!=='q'){state.filters[scope][key]=e.target.value;render();}});
document.addEventListener('input',e=>{const scope=e.target.dataset.filterScope;if(scope&&e.target.dataset.filterKey==='q'){state.filters[scope].q=e.target.value;if(scope==='stock')state.search='';refreshFilterResults(scope);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();$('menuToggle').focus({preventScroll:true});}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const buttons=[...$('nav').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}});
document.addEventListener('change',e=>{if(e.target.name==='task'&&$('selection'))$('selection').textContent=selectionSummary();if(e.target.id==='docStatus'){state.docFilter=e.target.value;render();}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)actions[b.dataset.action]?.(b.dataset.arg);});
document.addEventListener('submit',e=>{e.preventDefault();const id=e.target.id,code=$('scan')?.value.trim();if(id==='pickForm')pick(code);if(id==='stationForm')scanStation(code);if(id==='opForm')checkOp(code);if(id==='quickSearch'){state.search=$('quickCode').value.trim();navigate('Остатки');}if(id==='chatForm')question($('message').value);if(innerWidth>760)$('scan')?.focus({preventScroll:true});});
document.addEventListener('change',e=>{if(e.target.name==='task'){const id=e.target.value;if(e.target.checked)state.selected.push(id);else state.selected=state.selected.filter(x=>x!==id);$('selection').textContent=selectionSummary();e.target.closest('.order-line')?.classList.toggle('selected',e.target.checked);}if(op&&['product','qty','from','to','reason'].includes(e.target.id)){readOp();op.cellOk=false;op.checked=false;if(e.target.id==='product'){op.from=products[op.p].cell;op.to=op.kind===1?'C-1-2':op.from;}render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value.trim();$('stockRows').innerHTML=stockRows();}if(op&&['qty','reason'].includes(e.target.id)){op.checked=false;op.cellOk=false;}});
let openSelect=null;
function closeSelect(focus=true){if(!openSelect)return;const {panel,trigger}=openSelect;panel.remove();trigger.setAttribute('aria-expanded','false');openSelect=null;if(focus&&trigger.isConnected)trigger.focus({preventScroll:true});}
function enhanceSelects(){document.querySelectorAll('select').forEach(select=>{let trigger=select.nextElementSibling;if(!trigger?.classList.contains('select-trigger')){select.classList.add('native-select');select.tabIndex=-1;select.setAttribute('aria-hidden','true');trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.dataset.select=select.id;trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const label=select.closest('label');trigger.setAttribute('aria-label',label?[...label.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent.trim()).join(' '):select.id);select.after(trigger);trigger.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(openSelect?.trigger===trigger)closeSelect();else showSelect(select,trigger);});trigger.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();showSelect(select,trigger,e.key);}});}trigger.textContent=select.selectedOptions[0]?.textContent||'Выберите';trigger.disabled=select.disabled;});}
function showSelect(select,trigger,key){closeSelect(false);const panel=document.createElement('div');panel.className='select-menu';panel.id='select-options-'+select.id;panel.setAttribute('role','listbox');panel.setAttribute('aria-label',trigger.getAttribute('aria-label'));trigger.setAttribute('aria-controls',panel.id);trigger.setAttribute('aria-expanded','true');const options=[...select.options].filter(o=>!o.disabled);options.forEach(option=>{const item=document.createElement('button');item.type='button';item.className='select-option';item.textContent=option.textContent;item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.tabIndex=-1;item.onclick=e=>{e.preventDefault();e.stopPropagation();const id=select.id;closeSelect(false);select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));enhanceSelects();document.querySelector('[data-select="'+id+'"]')?.focus({preventScroll:true});};panel.append(item);});document.body.append(panel);const r=trigger.getBoundingClientRect(),width=Math.min(Math.max(r.width,210),innerWidth-20);panel.style.width=width+'px';panel.style.left=Math.max(10,Math.min(r.left,innerWidth-width-10))+'px';const below=innerHeight-r.bottom-12,above=r.top-12;const down=below>=Math.min(panel.scrollHeight,260)||below>=above;panel.style.maxHeight=Math.max(80,Math.min(300,down?below:above))+'px';if(down)panel.style.top=(r.bottom+6)+'px';else panel.style.bottom=(innerHeight-r.top+6)+'px';openSelect={panel,trigger};const items=[...panel.children];let index=key==='Home'?0:key==='End'?items.length-1:Math.max(0,options.findIndex(o=>o.selected));items[index]?.focus({preventScroll:true});panel.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeSelect();return;}if(e.key==='Tab'){closeSelect();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();index=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[index].focus();}};}
document.addEventListener('pointerdown',e=>{if(openSelect&&!openSelect.panel.contains(e.target)&&!openSelect.trigger.contains(e.target))closeSelect(false);});
document.addEventListener('change',()=>enhanceSelects());
for(const event of ['wheel','touchmove'])document.addEventListener(event,e=>{if(openSelect&&!openSelect.panel.contains(e.target))closeSelect(false);},{capture:true,passive:true});
$('cleanToggle').onclick=()=>{state.clean=!state.clean;if(state.clean)state.tour=false;render();applyMode();};
$('deviceToggle').onclick=()=>{const active=$('mode').value==='terminal';$('mode').value=active?'auto':'terminal';applyMode();navigate(active?(innerWidth<761?'Операции':'Смена'):'Операции');};
$('settingsToggle').onclick=()=>{const s=$('settings');s.hidden=!s.hidden;$('settingsToggle').setAttribute('aria-expanded',String(!s.hidden));};$('mode').onchange=()=>{applyMode();render();};$('role').onchange=()=>{if(op){op.cellOk=false;op.checked=false;}notice('Демонстрационная роль: '+role());render();};$('employee').onchange=render;
$('reset').onclick=()=>{if(confirm('Сбросить действия и начать учебную смену заново?')){state=fresh();state.inventory[0]['C-1-2']=6;op=null;notice('Учебная смена восстановлена');render();}};
window.addEventListener('resize',()=>{const before=isDesktop();closeSelect(false);applyMode();if(before!==isDesktop())render();});applyMode();render();
